async function resolveBestQualifiedName(tablePattern: string): Promise<string | null> {
  const tables = await getTableRefs();
  for (const schema of SCHEMA_PRIORITY) {
    const qualified = `${schema}.${tablePattern}`;
    if (tables.some(t => normalizeMainTableName(t.qualifiedName) === normalizeMainTableName(qualified))) {
      return qualified;
    }
  }
  const mainQualified = `main.${tablePattern}`;
  if (tables.some(t => normalizeMainTableName(t.qualifiedName) === normalizeMainTableName(mainQualified))) {
    return mainQualified;
  }
  return tablePattern; // fallback: use the pattern as-is
}

export async function buildIntentSchemaPrompt(intentCategory: string): Promise<string | null> {
  if (intentCategory === 'general' || intentCategory === 'cross_schema') {
    return null; // Use full system prompt
  }

  const tablePatterns = INTENT_TABLE_MAP[intentCategory];
  if (!tablePatterns || tablePatterns.length === 0) {
    return null;
  }

  // Resolve patterns to best qualified names
  const qualifiedTables: string[] = [];
  for (const pattern of tablePatterns) {
    const resolved = await resolveBestQualifiedName(pattern);
    qualifiedTables.push(resolved);
  }

  // Get column info for each resolved table
  const sections: string[] = ['Relevant tables and columns for this question:'];
  for (const qualifiedName of qualifiedTables) {
    const columns = await getColumns(qualifiedName);
    const visibleColumns = columns.slice(0, DETAILED_COLUMN_LIMIT);
    const rows = visibleColumns.map(col => `| ${col.name} | ${col.type} |`).join('\n');
    const more = columns.length > DETAILED_COLUMN_LIMIT
      ? `\n| ... | ${columns.length - DETAILED_COLUMN_LIMIT} more columns |`
      : '';
    sections.push(`## ${qualifiedName}\n| Column | Type |\n|--------|------|\n${rows}${more}`);
  }

  // Add intent-specific SQL templates
  const templates = INTENT_SQL_TEMPLATES[intentCategory];
  if (templates && templates.length > 0) {
    sections.push('SQL templates for this category:', ...templates);
  }

  sections.push(
    'Use these tables and templates to answer the question. You can still use other tools (list_nba_tables, get_schema_info) if needed, but the most relevant information is here.'
  );

  return sections.join('\n\n');
}
