async function validateAnswer(state: ChatbotStateType): Promise<Partial<ChatbotStateType> | Command> {
  const lastMessage = state.messages[state.messages.length - 1];
  if (!lastMessage || lastMessage._getType() !== 'ai') {
    return new Command({ goto: END });
  }

  const answerText = typeof lastMessage.content === 'string' ? lastMessage.content : '';
  if (!answerText) {
    return new Command({ goto: END });
  }

  // Extract numbers from answer
  const answerNumbers = extractLargeNumbers(answerText);
  if (answerNumbers.length === 0) {
    return new Command({ goto: END });
  }

  // Extract numbers from tool outputs
  const toolNumbers = extractNumbersFromToolMessages(state.messages);

  // Check for hallucinated numbers
  const hallucinated = answerNumbers.filter(n => !toolNumbers.has(n));
  if (hallucinated.length > 0) {
