input.content:
#!/usr/bin/env bun
/**
 * Iterative nemotron-nano-9b-v2 test with 3x runs, failure categorization, observability.
 * Runs 6 questions × 3 = 18 invocations per iteration.
 * 10-minute wall clock timeout.
 * Emits per-run traces for debugging.
 */

import { HumanMessage, SystemMessage, ToolMessage } from '@langchain/core/messages';
import { getChatbotGraph, resetGraph } from '../src/chatbot/agent/graph.js';
import type { ChatbotStateType } from '../src/chatbot/agent/state.js';
import { closeDb, initDb } from '../src/chatbot/db.js';
import { setModel } from '../src/chatbot/openrouter.js';
import { buildSystemPrompt } from '../src/chatbot/systemPrompt.js';

const MODEL = 'nvidia/nemotron-nano-9b-v2';
const TOTAL_TIMEOUT_MS = 10 * 60 * 1000; // 10 minutes
const PER_QUESTION_TIMEOUT_MS = 90_000; // 90s per run
const RUNS_PER_QUESTION = 3;

type FailureCategory =
  | 'sql_syntax'
  | 'sql_schema'
  | 'tool_loop'
  | 'hallucination'
  | 'wrong_answer'
  | 'refused'
  | 'no_clarification'
  | 'timeout'
  | 'crash';

interface RunResult {
  run: number;
  passed: boolean;
  answer: string;
  category?: FailureCategory;
  details?: string;
  toolCalls: number;
  duration: number;
}

interface QuestionResult {
  id: string;
  question: string;
  expected: string;
  tier: string;
  runs: RunResult[];
  passCount: number;
  totalCount: number;
}

const QUESTIONS = [
  { id: 'simple-001', q: 'Who is the all-time NBA regular season scoring leader?', expected: 'LeBron James', tier: 'simple' },
  { id: 'simple-002', q: 'How many career points does LeBron James have?', expected: '43440', tier: 'simple' },
  { id: 'simple-003', q: 'Who won the NBA MVP award in the 2023-24 season?', expected: 'Nikola', tier: 'simple' },
  { id: 'multi-001', q: 'Who has more career points: Michael Jordan or Kobe Bryant?', expected: 'Kobe', tier: 'multi-step' },
  { id: 'vague-001', q: 'Who scored the most?', expected: 'CLARIFICATION', tier: 'vague' },
  { id: 'specific-001', q: 'What was Michael Jordan PER in the 1995 playoffs?', expected: 'NOT_AVAILABLE', tier: 'overly-specific' },
];

function extractBestAnswer(messages: Array<{ content?: string | object }>): string {
  for (let i = messages.length - 1; i >= 0; i--) {
    const content = String(messages[i].content || '');
    const trimmed = content.trim();
    if (trimmed.length > 0 && !trimmed.includes('STOP. You have been calling')) {
      return trimmed;
    }
  }
  return '';
}

function countToolCalls(state: ChatbotStateType): number {
  return state.totalToolCalls ?? 0;
}

function categorize(sqlResult: boolean, answer: string, expected: string, toolCalls: number, hasError: boolean): FailureCategory {
  if (hasError) return 'crash';
  if (toolCalls >= 19) return 'tool_loop';
  if (expected === 'CLARIFICATION' && !sqlResult) return 'no_clarification';
  if (expected === 'NOT_AVAILABLE' && !sqlResult) return 'refused';
  if (!sqlResult) {
    if (answer.toLowerCase().includes('syntax error') || answer.toLowerCase().includes('parse error')) return 'sql_syntax';
    if (answer.toLowerCase().includes('does not exist') || answer.toLowerCase().includes('no such')) return 'sql_schema';
    return 'wrong_answer';
  }
  return 'wrong_answer';
}

async function main(): Promise<void> {
  const startTime = Date.now();
  await initDb();
  const prompt = await buildSystemPrompt();

  console.log(`\n=== ${MODEL} — ${RUNS_PER_QUESTION} runs × ${QUESTIONS.length} questions ===\n`);

  setModel(MODEL);
  resetGraph();

  const results: QuestionResult[] = [];
  const deadline = startTime + TOTAL_TIMEOUT_MS;
  let totalPassed = 0;
  let totalRuns = 0;

  for (const q of QUESTIONS) {
    if (Date.now() >= deadline) {
      console.log(`[TIMEOUT] Stopping at ${q.id} — total time exceeded\n`);
      break;
    }

    const qr: QuestionResult = {
      id: q.id,
      question: q.q,
      expected: q.expected,
      tier: q.tier,
      runs: [],
      passCount: 0,
      totalCount: RUNS_PER_QUESTION,
    };

    for (let run = 1; run <= RUNS_PER_QUESTION; run++) {
      totalRuns++;
      const runDeadline = Math.min(Date.now() + PER_QUESTION_TIMEOUT_MS, deadline);
      const runStart = Date.now();

      process.stdout.write(`[${q.id}] run ${run}/${RUNS_PER_QUESTION}... `);

      try {
        const threadId = `nemotron-${q.id}-run-${run}-${Date.now()}`;
        const result = await Promise.race([
          getChatbotGraph().invoke(
            { messages: [new SystemMessage(prompt), new HumanMessage(q.q)] },
            { configurable: { thread_id: threadId }, recursionLimit: 50 },
          ),
          new Promise<never>((_, reject) =>
            setTimeout(() => reject(new Error('PER_QUESTION_TIMEOUT')), PER_QUESTION_TIMEOUT_MS),
          ),
        ]);

        const answer = extractBestAnswer(result.messages);
        const toolCalls = countToolCalls(result.values as ChatbotStateType);
        const duration = Date.now() - runStart;

        let passed: boolean;
        if (q.expected === 'CLARIFICATION') {
          passed = answer.toLowerCase().includes('clarif') || answer.toLowerCase().includes('specify');
        } else if (q.expected === 'NOT_AVAILABLE') {
          passed = answer.toLowerCase().includes('not available') || answer.toLowerCase().includes('do not have');
        } else {
          passed = answer.includes(q.expected);
        }

        const category = categorize(passed, answer, q.expected, toolCalls, false);
        if (passed) totalPassed++;

        console.log(passed ? 'PASS' : `FAIL [${category}]`);
        if (!passed) {
          const detail = category === 'tool_loop'
            ? `toolCalls=${toolCalls}`
            : answer.slice(0, 100);
          console.log(`  ${detail}`);

          // Observability: log tool messages for debugging
          const traceMsgs = result.messages.filter(m => ToolMessage.isInstance(m));
          if (traceMsgs.length > 0) {
            for (const tm of traceMsgs.slice(-2)) {
              const c = String(tm.content).slice(0, 80);
              console.log(`  tool: ${tm.name} → ${c}`);
            }
          }
        }

        qr.runs.push({ run, passed, answer: answer.slice(0, 200), category, details: undefined, toolCalls, duration });
        if (passed) qr.passCount++;

      } catch (e: unknown) {
        const isTimeout = e instanceof Error && e.message === 'PER_QUESTION_TIMEOUT';
        const category: FailureCategory = isTimeout ? 'timeout' : 'crash';
        const duration = Date.now() - runStart;

        console.log(isTimeout ? 'FAIL [timeout]' : 'FAIL [crash]');
        if (!isTimeout) {
          const msg = e instanceof Error ? e.message : String(e);
          console.log(`  ${msg.slice(0, 120)}`);
        }

        qr.runs.push({
          run,
          passed: false,
          answer: '',
          category,
          details: e instanceof Error ? e.message : String(e),
          toolCalls: 0,
          duration,
        });
      }

      if (Date.now() >= deadline) {
        console.log(`  [TIMEOUT] Stopping ${q.id} after run ${run}/${RUNS_PER_QUESTION}\n`);
        break;
      }
    }

    results.push(qr);

    // Per-question summary
    const passStr = `${qr.passCount}/${qr.runs.length}`;
    console.log(`  → ${q.id} (${q.tier}): ${passStr} pass`);
    const failures = qr.runs.filter(r => !r.passed).map(r => `run-${r.run}:${r.category ?? '?'}`);
    if (failures.length > 0) console.log(`  → failures: ${failures.join(', ')}`);
    console.log('');
  }

  // Final summary
  const elapsed = Math.round((Date.now() - startTime) / 1000);
  const totalPossible = results.reduce((s, r) => s + r.totalCount, 0);
  const attempted = results.reduce((s, r) => s + r.runs.length, 0);
  console.log(`=== Results: ${totalPassed}/${attempted} PASS (attempted ${attempted}/${totalPossible}) in ${elapsed}s ===`);

  // Per-question breakdown
  console.log('\nBreakdown:');
  for (const r of results) {
    const pct = r.passCount > 0 ? Math.round(r.passCount / r.runs.length * 100) : 0;
    const cats = [...new Set(r.runs.filter(x => !x.passed).map(x => x.category ?? '?'))];
    console.log(`  ${r.id} (${r.tier}): ${r.passCount}/${r.runs.length} (${pct}%) ${cats.length ? `cats: [${cats.join(', ')}]` : '✅'}`);
  }

  await closeDb();
}

main().catch(e => {
  console.error('FATAL:', e);
  process.exit(1);
});

