#!/usr/bin/env bun
/**
 * Iterative nemotron-nano-9b-v2 test with streaming observability.
 * Each question streams tokens, tool calls, and chain stages in real-time.
 * 5-minute wall clock timeout. Exits cleanly.
 */

import { HumanMessage, SystemMessage } from '@langchain/core/messages';
import { resetGraph } from '../src/chatbot/agent/graph.js';
import { streamQuery, type StreamEvent } from '../src/chatbot/agent/streaming.js';
import { closeDb, initDb } from '../src/chatbot/db.js';
import { setModel } from '../src/chatbot/openrouter.js';
import { buildSystemPrompt } from '../src/chatbot/systemPrompt.js';

const MODEL = 'nvidia/nemotron-nano-9b-v2';
const TOTAL_TIMEOUT_MS = 5 * 60 * 1000;
const RUNS_PER_QUESTION = 3;
const TAB = '  ';

type FailureCategory =
  | 'sql_syntax' | 'sql_schema' | 'tool_loop' | 'hallucination'
  | 'wrong_answer' | 'refused' | 'no_clarification' | 'timeout' | 'crash';

interface Question {
  id: string; q: string; expected: string; tier: string;
}

const QUESTIONS: Question[] = [
  { id: 'simple-001', q: 'Who is the all-time NBA regular season scoring leader?', expected: 'LeBron James', tier: 'simple' },
  { id: 'simple-002', q: 'How many career points does LeBron James have?', expected: '43440', tier: 'simple' },
  { id: 'simple-003', q: 'Who won the NBA MVP award in the 2023-24 season?', expected: 'Nikola', tier: 'simple' },
  { id: 'multi-001', q: 'Who has more career points: Michael Jordan or Kobe Bryant?', expected: 'Kobe', tier: 'multi-step' },
  { id: 'vague-001', q: 'Who scored the most?', expected: 'CLARIFICATION', tier: 'vague' },
  { id: 'specific-001', q: 'What was Michael Jordan PER in the 1995 playoffs?', expected: 'NOT_AVAILABLE', tier: 'overly-specific' },
];

function categorize(run: { passed: boolean; answer: string; toolCalls: number }, expected: string): FailureCategory {
  if (run.toolCalls >= 19) return 'tool_loop';
  if (expected === 'CLARIFICATION' && !run.passed) return 'no_clarification';
  if (expected === 'NOT_AVAILABLE' && !run.passed) return 'refused';
  if (!run.passed) {
    const a = run.answer.toLowerCase();
    if (/syntax error|parse error/.test(a)) return 'sql_syntax';
    if (/does not exist|no such/.test(a)) return 'sql_schema';
    return 'wrong_answer';
  }
  return 'wrong_answer';
}

async function streamQuestion(q: Question, run: number, prompt: string, deadline: number): Promise<{
  passed: boolean; answer: string; toolCalls: number; events: string[];
}> {
  const threadId = `nemotron-${q.id}-r${run}-${Date.now()}`;
  let answerText = '';
  let toolCalls = 0;
  const events: string[] = [];

  try {
    const gen = streamQuery(
      [new SystemMessage(prompt), new HumanMessage(q.q)],
      threadId,
    );

    for await (const event of gen) {
      if (Date.now() >= deadline) throw new Error('TIME_EXCEEDED');

      switch (event.type) {
        case 'chain_stage':
          events.push(`[${event.stage}]`);
          break;
        case 'token':
          process.stdout.write(event.content);
          answerText += event.content;
          break;
        case 'tool_start':
          toolCalls++;
          const input = JSON.stringify(event.input).slice(0, 120);
          events.push(`\n${TAB}→ tool: ${event.name}(${input})`);
          process.stdout.write(`\n${TAB}→ 🔧 ${event.name}`);
          break;
        case 'tool_end': {
          const out = event.output.slice(0, 100);
          events.push(`${TAB}  ${out}`);
          process.stdout.write(` ✅\n${TAB}${out}`);
          break;
        }
        case 'tool_error':
          events.push(`${TAB}  ❌ ${event.error.slice(0, 80)}`);
          process.stdout.write(` ❌\n${TAB}${event.error.slice(0, 80)}`);
          break;
        case 'usage':
          events.push(`${TAB}tokens: ${event.usage.inputTokens}→${event.usage.outputTokens}`);
          break;
        case 'done':
          answerText = event.messages
            .map(m => String(m.content || ''))
            .filter(c => c.length > 0)
            .reverse()[0] || answerText;
          break;
        case 'error':
          throw new Error(event.message);
      }
    }
  } catch (e) {
    if (e instanceof Error && e.message === 'TIME_EXCEEDED') {
      events.push('[TIME_EXCEEDED]');
      process.stdout.write('\n[TIMEOUT]');
    } else {
      const msg = e instanceof Error ? e.message : String(e);
      events.push(`[ERROR: ${msg.slice(0, 80)}]`);
      process.stdout.write(`\n[${msg.slice(0, 60)}]`);
    }
    throw e;
  }

  const passed = q.expected === 'CLARIFICATION'
    ? /clarif|specify/i.test(answerText)
    : q.expected === 'NOT_AVAILABLE'
      ? /not available|do not have/i.test(answerText)
      : answerText.includes(q.expected);

  return { passed, answer: answerText.slice(0, 200), toolCalls, events };
}

async function main() {
  const startTime = Date.now();
  const deadline = startTime + TOTAL_TIMEOUT_MS;

  await initDb();
  const prompt = await buildSystemPrompt();

  process.env['OPENROUTER_API_KEY'] = process.env['OPENROUTER_API_KEY'];
  setModel(MODEL);
  resetGraph();

  console.log(`\n┌─ ${MODEL} — ${RUNS_PER_QUESTION}runs × ${QUESTIONS.length}questions`);
  console.log(`├─ timeout: ${TOTAL_TIMEOUT_MS / 1000}s wall`);
  console.log(`└${'─'.repeat(50)}\n`);

  let totalPassed = 0;
  let totalAttempted = 0;

  for (const q of QUESTIONS) {
    if (Date.now() >= deadline) { console.log(`⏰ Wall timeout — stopping at ${q.id}`); break; }

    console.log(`\n══════════ ${q.id} (${q.tier}): ${q.q} ═════════\n`);

    let qPassed = 0;
    let qRuns = 0;

    for (let run = 1; run <= RUNS_PER_QUESTION && Date.now() < deadline; run++) {
      qRuns++;
      process.stdout.write(`\n── run ${run}/${RUNS_PER_QUESTION} ──\n`);

      try {
        const result = await streamQuestion(q, run, prompt, deadline);
        totalAttempted++;
        if (result.passed) { totalPassed++; qPassed++; }

        const cat = categorize(result, q.expected);
        process.stdout.write(`\n${result.passed ? '✅ PASS' : `❌ FAIL [${cat}]`} (tools:${result.toolCalls})\n`);
      } catch {
        totalAttempted++;
        process.stdout.write(`\n❌ FAIL [timeout]\n`);
      }
    }

    console.log(`\n── ${q.id} result: ${qPassed}/${qRuns} pass ──\n`);
  }

  const elapsed = Math.round((Date.now() - startTime) / 1000);
  console.log(`\n${'═'.repeat(50)}`);
  console.log(`RESULT: ${totalPassed}/${totalAttempted} PASS in ${elapsed}s`);
  console.log(`${'═'.repeat(50)}\n`);

  await closeDb();
}

main().catch(e => { console.error('\nFATAL:', e); process.exit(1); });

